import os
import json
import time
import random
import hashlib
import datetime
from typing import Any, Dict, List, Optional, Tuple
from openai import OpenAI

def env_str(name: str, default: Optional[str] = None) -> Optional[str]:
    v = os.environ.get(name)
    if v is None or v == "":
        return default
    return v

def env_int(name: str, default: int) -> int:
    v = os.environ.get(name)
    if v is None or v == "":
        return default
    try:
        return int(v)
    except Exception:
        return default

def env_float(name: str, default: float) -> float:
    v = os.environ.get(name)
    if v is None or v == "":
        return default
    try:
        return float(v)
    except Exception:
        return default

def now_utc_iso() -> str:
    return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

def sha256_hex(s: str) -> str:
    return hashlib.sha256(s.encode("utf-8")).hexdigest()

def safe_mkdir(path: str) -> None:
    os.makedirs(path, exist_ok=True)

def clamp_int(x: int, lo: int, hi: int) -> int:
    if x < lo:
        return lo
    if x > hi:
        return hi
    return x

def looks_hungarian(text: str) -> bool:
    if not text or len(text) < 200:
        return False
    hu_chars = "áéíóöőúüűÁÉÍÓÖŐÚÜŰ"
    hu_count = sum(1 for ch in text if ch in hu_chars)
    alpha_count = sum(1 for ch in text if ch.isalpha())
    if alpha_count == 0:
        return False
    ratio = hu_count / max(1, alpha_count)
    if hu_count >= 6:
        return True
    if ratio >= 0.003:
        return True
    common = ["hogy", "és", "nem", "van", "mert", "szerint", "külön", "ugyan", "továbbá", "valamint"]
    hits = sum(1 for w in common if w in text.lower())
    return hits >= 3

def extract_response_text_and_citations(resp: Any) -> Tuple[str, List[str]]:
    d = None
    if hasattr(resp, "model_dump"):
        try:
            d = resp.model_dump()
        except Exception:
            d = None
    if d is None and isinstance(resp, dict):
        d = resp
    if d is None:
        try:
            d = json.loads(str(resp))
        except Exception:
            d = {}

    citations_urls: List[str] = []
    c = d.get("citations")
    if isinstance(c, list):
        for item in c:
            if isinstance(item, dict):
                u = item.get("url") or item.get("source") or item.get("link")
                if isinstance(u, str) and u.startswith("http"):
                    citations_urls.append(u)
            elif isinstance(item, str) and item.startswith("http"):
                citations_urls.append(item)

    if isinstance(d.get("output_text"), str):
        return d["output_text"], list(dict.fromkeys(citations_urls))

    output = d.get("output")
    if isinstance(output, list):
        parts: List[str] = []
        for item in output:
            if not isinstance(item, dict):
                continue
            if item.get("type") in ("output_text", "text"):
                t = item.get("text")
                if isinstance(t, str):
                    parts.append(t)
                else:
                    content = item.get("content")
                    if isinstance(content, list):
                        for c2 in content:
                            if isinstance(c2, dict) and c2.get("type") in ("output_text", "text"):
                                t2 = c2.get("text")
                                if isinstance(t2, str):
                                    parts.append(t2)
            if item.get("type") == "message":
                content = item.get("content")
                if isinstance(content, list):
                    for c2 in content:
                        if isinstance(c2, dict) and c2.get("type") in ("output_text", "text"):
                            t2 = c2.get("text")
                            if isinstance(t2, str):
                                parts.append(t2)
        if parts:
            return "".join(parts), list(dict.fromkeys(citations_urls))

    return "", list(dict.fromkeys(citations_urls))

def parse_json_lenient(s: str) -> Optional[Dict[str, Any]]:
    if not isinstance(s, str) or not s.strip():
        return None
    s2 = s.strip()
    try:
        return json.loads(s2)
    except Exception:
        pass
    start = s2.find("{")
    end = s2.rfind("}")
    if start != -1 and end != -1 and end > start:
        try:
            return json.loads(s2[start:end + 1])
        except Exception:
            return None
    return None

def ensure_schema(obj: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    if not isinstance(obj, dict):
        return None
    required_top = ["id", "kind", "language", "domain", "difficulty", "content", "safety"]
    for k in required_top:
        if k not in obj:
            return None
    if obj.get("language") != "hu":
        return None
    if not isinstance(obj.get("id"), str) or len(obj["id"]) < 8:
        return None
    if obj.get("kind") not in ["article", "dialogue", "qa", "instructions", "code", "math", "reasoning"]:
        return None
    if not isinstance(obj.get("domain"), str) or len(obj["domain"]) < 2:
        return None
    if obj.get("difficulty") not in ["alap", "kozep", "halado", "elit"]:
        return None
    if not isinstance(obj.get("content"), str) or len(obj["content"]) < 800:
        return None
    safety = obj.get("safety")
    if not isinstance(safety, dict):
        return None
    if safety.get("pii") is not False:
        return None
    if safety.get("copyright_safe") is not True:
        return None
    if safety.get("hallucination_risk") not in ["low", "medium"]:
        return None
    if not looks_hungarian(obj["content"]):
        return None
    return obj

def build_schema() -> Dict[str, Any]:
    return {
        "type": "object",
        "additionalProperties": False,
        "properties": {
            "id": {"type": "string"},
            "kind": {"type": "string", "enum": ["article", "dialogue", "qa", "instructions", "code", "math", "reasoning"]},
            "language": {"type": "string", "enum": ["hu"]},
            "domain": {"type": "string"},
            "difficulty": {"type": "string", "enum": ["alap", "kozep", "halado", "elit"]},
            "sources": {"type": "array", "items": {"type": "string"}, "minItems": 0},
            "content": {"type": "string"},
            "safety": {
                "type": "object",
                "additionalProperties": False,
                "properties": {
                    "pii": {"type": "boolean", "enum": [False]},
                    "copyright_safe": {"type": "boolean", "enum": [True]},
                    "hallucination_risk": {"type": "string", "enum": ["low", "medium"]},
                    "notes": {"type": "string"}
                },
                "required": ["pii", "copyright_safe", "hallucination_risk", "notes"]
            }
        },
        "required": ["id", "kind", "language", "domain", "difficulty", "content", "safety"]
    }

def make_task_catalog() -> List[Dict[str, str]]:
    return [
        {"kind": "article", "domain": "magyar_nyelvtan", "difficulty": "kozep"},
        {"kind": "article", "domain": "helyesiras", "difficulty": "halado"},
        {"kind": "dialogue", "domain": "stilus_retorika", "difficulty": "halado"},
        {"kind": "qa", "domain": "altalanos_muveletsegi", "difficulty": "kozep"},
        {"kind": "qa", "domain": "magyar_tortenelem", "difficulty": "halado"},
        {"kind": "qa", "domain": "magyar_foldrajz", "difficulty": "kozep"},
        {"kind": "qa", "domain": "jog_es_kozigazgatas", "difficulty": "halado"},
        {"kind": "instructions", "domain": "iraskeszseg", "difficulty": "kozep"},
        {"kind": "instructions", "domain": "szovegszerkesztes", "difficulty": "halado"},
        {"kind": "reasoning", "domain": "logika_erveles", "difficulty": "halado"},
        {"kind": "math", "domain": "matematika_alapok", "difficulty": "kozep"},
        {"kind": "math", "domain": "valoszinusegszamitas", "difficulty": "halado"},
        {"kind": "code", "domain": "programozas_python", "difficulty": "kozep"},
        {"kind": "code", "domain": "programozas_rendszertervezes", "difficulty": "halado"},
        {"kind": "article", "domain": "term_tudomany_alapok", "difficulty": "kozep"},
        {"kind": "article", "domain": "egeszseg_es_biologia", "difficulty": "kozep"},
        {"kind": "article", "domain": "kozgazdasagtan_alapok", "difficulty": "halado"},
        {"kind": "dialogue", "domain": "ugyfelszolgalat_szimulacio", "difficulty": "kozep"},
        {"kind": "dialogue", "domain": "targyalastechnika", "difficulty": "halado"},
        {"kind": "reasoning", "domain": "kritikus_gondolkodas", "difficulty": "elit"}
    ]

def build_prompt(task: Dict[str, str], seed: int) -> str:
    kind = task["kind"]
    domain = task["domain"]
    difficulty = task["difficulty"]
    return (
        "Kizárólag magyar nyelven dolgozz.\n"
        "Kizárólag eredeti, saját szöveget írj; semmit ne idézz szó szerint külső forrásból.\n"
        "Ne találj ki tényeket. Ha valami nem biztos, inkább hagyd ki, vagy jelöld bizonytalanként, és csökkentsd a kockázatot.\n"
        "Ne írj személyes adatot (valós név+cím+telefonszám, e-mail, azonosító, jelszó, bankkártya), és ne modellezz valós személyeket.\n"
        "A kimenetnek a megadott JSON sémát kell követnie.\n"
        f"Feladat típusa: {kind}\n"
        f"Domain: {domain}\n"
        f"Nehézség: {difficulty}\n"
        f"Seed: {seed}\n"
        "Tartalmi követelmények:\n"
        "- A szöveg legyen rendkívül tiszta, tömör, mégis mély; kerülje a felesleges frázisokat.\n"
        "- Pretrain-jelleg: adjon sok, nyelvileg változatos, természetes magyar példát, de szakmailag is precíz legyen.\n"
        "- Ha tényszerű (pl. történelem, jog, földrajz), akkor használd a websearch eszközt, és csak a toolból származó információkra támaszkodj.\n"
        "- A 'sources' mezőbe csak valós, ellenőrizhető URL-ek kerüljenek, amelyek a tool hivatkozásai.\n"
        "- A 'safety.hallucination_risk' legyen 'low' vagy 'medium'. Törekedj a 'low'-ra.\n"
        "- A 'content' legyen legalább 800 karakter.\n"
    )

class RotatingJsonlWriter:
    def __init__(self, out_dir: str, prefix: str, bytes_per_file: int) -> None:
        self.out_dir = out_dir
        self.prefix = prefix
        self.bytes_per_file = bytes_per_file
        self.index_path = os.path.join(out_dir, f"{prefix}.state.json")
        self.file_index = 1
        self.bytes_written_current = 0
        self.fh = None
        safe_mkdir(out_dir)
        self._load_state()
        self._open_current()

    def _load_state(self) -> None:
        try:
            with open(self.index_path, "rb") as f:
                st = json.loads(f.read().decode("utf-8"))
            if isinstance(st, dict):
                self.file_index = int(st.get("file_index", 1))
        except Exception:
            self.file_index = 1

    def _save_state(self) -> None:
        st = {"file_index": self.file_index, "updated_at": now_utc_iso()}
        tmp = self.index_path + ".tmp"
        with open(tmp, "wb") as f:
            f.write(json.dumps(st, ensure_ascii=False).encode("utf-8"))
        os.replace(tmp, self.index_path)

    def _file_path(self, idx: int) -> str:
        return os.path.join(self.out_dir, f"{self.prefix}_{idx:06d}.jsonl")

    def _open_current(self) -> None:
        if self.fh is not None:
            try:
                self.fh.close()
            except Exception:
                pass
        path = self._file_path(self.file_index)
        self.fh = open(path, "ab")
        try:
            self.fh.seek(0, 2)
            self.bytes_written_current = self.fh.tell()
        except Exception:
            self.bytes_written_current = 0

    def _rotate(self) -> None:
        self.file_index += 1
        self._save_state()
        self._open_current()

    def write_obj(self, obj: Dict[str, Any]) -> None:
        line = (json.dumps(obj, ensure_ascii=False) + "\n").encode("utf-8")
        if self.bytes_written_current + len(line) > self.bytes_per_file:
            self._rotate()
        self.fh.write(line)
        self.fh.flush()
        self.bytes_written_current += len(line)

def main() -> None:
    api_key = env_str("XAI_API_KEY")
    if not api_key:
        raise ValueError("XAI_API_KEY environment variable not set")

    base_url = env_str("XAI_BASE_URL", "")
    model = env_str("XAI_MODEL", "grok-4-1-fast")
    out_dir = env_str("OUT_DIR", "datasets_hu_pretrain") or "datasets_hu_pretrain"
    prefix = env_str("FILE_PREFIX", "hu_pretrain") or "hu_pretrain"
    bytes_per_file = env_int("BYTES_PER_FILE", 1048576)
    sleep_s = env_float("SLEEP_SECONDS", 0.2)
    temperature = env_float("TEMPERATURE", 0.35)
    max_output_tokens = env_int("MAX_OUTPUT_TOKENS", 131072)
    max_output_tokens = clamp_int(max_output_tokens, 1024, 262144)

    seed_base = env_int("SEED", int(time.time()))
    rng = random.Random(seed_base)

    client = OpenAI(api_key=api_key, base_url=base_url)
    writer = RotatingJsonlWriter(out_dir=out_dir, prefix=prefix, bytes_per_file=bytes_per_file)

    schema = build_schema()
    catalog = make_task_catalog()

    produced = 0
    consecutive_failures = 0
    backoff = 1.0

    while True:
        seed = rng.randrange(0, 2_000_000_000)
        task = catalog[rng.randrange(0, len(catalog))]
        prompt = build_prompt(task, seed)

        want_search = task["domain"] in {
            "altalanos_muveletsegi",
            "magyar_tortenelem",
            "magyar_foldrajz",
            "jog_es_kozigazgatas",
            "kozgazdasagtan_alapok",
            "term_tudomany_alapok",
            "egeszseg_es_biologia"
        }

        tools = []
        if want_search:
            tools = [{"type": "websearch"}]

        request = {
            "model": model,
            "input": [
                {
                    "role": "system",
                    "content": [
                        {
                            "type": "text",
                            "text": "Te egy rendkívül precíz, magyar nyelvű pretrain-dataset generátor vagy. Cél: hibamentes, tiszta, sokszínű magyar nyelvi anyag, minimális hallucinációs kockázattal."
                        }
                    ]
                },
                {
                    "role": "user",
                    "content": [
                        {"type": "text", "text": prompt}
                    ]
                }
            ],
            "tools": tools,
            "text": {
                "format": {
                    "type": "json_schema",
                    "strict": True,
                    "schema": schema
                }
            },
            "temperature": temperature,
            "max_output_tokens": max_output_tokens
        }

        try:
            resp = client.responses.create(**request)
            text, citations = extract_response_text_and_citations(resp)
            obj_raw = parse_json_lenient(text)

            if obj_raw is None:
                consecutive_failures += 1
                raise RuntimeError("Model output not valid JSON")

            if "sources" not in obj_raw or not isinstance(obj_raw.get("sources"), list):
                obj_raw["sources"] = []
            if citations:
                merged = []
                for u in obj_raw["sources"]:
                    if isinstance(u, str) and u.startswith("http"):
                        merged.append(u)
                for u in citations:
                    if isinstance(u, str) and u.startswith("http"):
                        merged.append(u)
                obj_raw["sources"] = list(dict.fromkeys(merged))

            obj = ensure_schema(obj_raw)
            if obj is None:
                consecutive_failures += 1
                raise RuntimeError("Schema validation failed")

            content = obj["content"]
            obj_out = {
                "id": obj["id"],
                "kind": obj["kind"],
                "language": "hu",
                "domain": obj["domain"],
                "difficulty": obj["difficulty"],
                "sources": obj.get("sources", []),
                "content": content,
                "safety": obj["safety"],
                "meta": {
                    "generated_at": now_utc_iso(),
                    "model": model,
                    "seed": seed,
                    "checksum_sha256": sha256_hex(content)
                }
            }

            writer.write_obj(obj_out)
            produced += 1
            consecutive_failures = 0
            backoff = 1.0

            if sleep_s > 0:
                time.sleep(sleep_s)

        except KeyboardInterrupt:
            break
        except Exception:
            consecutive_failures += 1
            if consecutive_failures >= 3:
                backoff = min(backoff * 1.8, 60.0)
            time.sleep(backoff)

if __name__ == "__main__":
    main()
