def call_responses_structured(client: OpenAI, model: str, prompt: str, schema: Dict[str, Any], tools: List[Dict[str, Any]], temperature: float, max_output_tokens: int) -> Tuple[Dict[str, Any], List[str]]:
    request = {
        "model": model,
        "input": [
            {
                "role": "system",
                "content": [
                    {
                        "type": "text",
                        "text": "Te egy rendkívül precíz, magyar nyelvű pretrain-dataset generátor vagy. A cél: hibamentes, tiszta, sokszínű magyar nyelvi anyag, minimális hallucinációs kockázattal. Kizárólag a megadott JSON sémának megfelelő objektumot adj vissza."
                    }
                ]
            },
            {
                "role": "user",
                "content": [
                    {"type": "text", "text": prompt}
                ]
            }
        ],
        "tools": tools,
        "text": {
            "format": {
                "type": "json_schema",
                "strict": True,
                "schema": schema
            }
        },
        "temperature": temperature,
        "max_output_tokens": max_output_tokens
    }
    resp = client.responses.create(**request)
    text, citations = extract_response_text_and_citations(resp)
    obj_raw = parse_json_lenient(text)
    if obj_raw is None:
        raise RuntimeError("responses.create nem JSON-t adott vissza")
    if "sources" not in obj_raw or not isinstance(obj_raw.get("sources"), list):
        obj_raw["sources"] = []
    if citations:
        merged = []
        for u in obj_raw["sources"]:
            if isinstance(u, str) and u.startswith("http"):
                merged.append(u)
        for u in citations:
            if isinstance(u, str) and u.startswith("http"):
                merged.append(u)
        obj_raw["sources"] = list(dict.fromkeys(merged))
    obj = ensure_schema(obj_raw)
    if obj is None:
        raise RuntimeError("responses.create JSON nem felelt meg a sémának")
    return obj, obj.get("sources", [])

def call_chat_structured(client: OpenAI, model: str, prompt: str, schema: Dict[str, Any], temperature: float, max_output_tokens: int) -> Dict[str, Any]:
    messages = [
        {
            "role": "system",
            "content": "Te egy rendkívül precíz, magyar nyelvű pretrain-dataset generátor vagy. Kizárólag a megadott JSON sémának megfelelő objektumot adj vissza."
        },
        {
            "role": "user",
            "content": prompt
        }
    ]
    completion = client.chat.completions.create(
        model=model,
        messages=messages,
        temperature=temperature,
        max_tokens=max_output_tokens
    )
    content = completion.choices[0].message.content if completion and completion.choices else ""
    obj_raw = parse_json_lenient(content or "")
    if obj_raw is None:
        raise RuntimeError("chat.completions nem JSON-t adott vissza")
    if "sources" not in obj_raw or not isinstance(obj_raw.get("sources"), list):
        obj_raw["sources"] = []
    obj = ensure_schema(obj_raw)
    if obj is None:
        raise RuntimeError("chat.completions JSON nem felelt meg a sémának")
    return obj

