        }

        tools: List[Dict[str, Any]] = []
        if want_search:
            tools = [{"type": "websearch"}]

        print(f"REQ {now_utc_iso()} n={produced+1} kind={task['kind']} domain={task['domain']} diff={task['difficulty']} websearch={str(want_search).lower()}", flush=True)

        try:
            try:
                obj, _ = call_responses_structured(
                    client=client,
                    model=model,
                    prompt=prompt,
                    schema=schema,
                    tools=tools,
                    temperature=temperature,
                    max_output_tokens=max_output_tokens
                )
                gen_mode = "responses_structured"
            except Exception as e1:
                if want_search:
                    raise
                obj = call_chat_structured(
                    client=client,
                    model=model,
                    prompt=prompt,
                    schema=schema,
                    temperature=temperature,
                    max_output_tokens=max_output_tokens
                )
                gen_mode = "chat_structured_fallback"

            content = obj["content"]
            obj_out = {
                "id": obj["id"],
                "kind": obj["kind"],
                "language": "hu",
                "domain": obj["domain"],
                "difficulty": obj["difficulty"],
                "sources": obj.get("sources", []),
                "content": content,
                "safety": obj["safety"],
