                    "generated_at": now_utc_iso(),
                    "model": model,
                    "seed": seed,
                    "generator": gen_mode,
                    "checksum_sha256": sha256_hex(content)
                }
            }

            path, idx, b = writer.write_obj(obj_out)
            produced += 1
            consecutive_failures = 0
            backoff = 1.0

            print(f"OK  {now_utc_iso()} n={produced} file={os.path.basename(path)} file_index={idx} file_bytes={b}", flush=True)

            if sleep_s > 0:
                time.sleep(sleep_s)

        except KeyboardInterrupt:
            print(f"STOP {now_utc_iso()} produced={produced}", flush=True)
            break
        except Exception as e:
            consecutive_failures += 1
            et = repr(e)
            print(f"ERR {now_utc_iso()} failures={consecutive_failures} backoff={backoff:.2f}s error={et}", file=sys.stderr, flush=True)
            if consecutive_failures >= 3:
                backoff = min(backoff * 1.8, 60.0)
            time.sleep(backoff)

