        "- A content legyen hibamentes, nyelvileg tiszta, változatos, és pretrain-szerűen gazdag.\n"
        "- A content legyen legalább 1200 karakter.\n"
        "- Ha a domain tényszerű, a sources tömbbe csak valós URL-eket tegyél, amelyek a websearchből származnak.\n"
        "- A kind-nek, domain-nek, difficulty-nek pontosan meg kell egyeznie a feladatban megadottakkal.\n"
        "Kimeneti követelmény:\n"
        "- A JSON feleljen meg a megadott sémának.\n"
        f"KÖTELEZŐ: kind={kind}\n"
        f"KÖTELEZŐ: domain={domain}\n"
        f"KÖTELEZŐ: difficulty={difficulty}\n"
    )

def _mk_item_id(seed: int, kind: str, domain: str, content: str) -> str:
    h = hashlib.sha256()
    h.update(str(seed).encode("utf-8"))
    h.update(b"|")
    h.update(kind.encode("utf-8"))
    h.update(b"|")
    h.update(domain.encode("utf-8"))
    h.update(b"|")
    h.update(content[:512].encode("utf-8", errors="ignore"))
    return h.hexdigest()[:24]

def _quality_gate(content: str, min_chars: int) -> Tuple[bool, str]:
    if not isinstance(content, str):
        return False, "content_not_string"
    t = content.strip()
    if len(t) < min_chars:
        return False, "content_too_short"
    if "\uFFFD" in t:
        return False, "replacement_char"
    if t.count("{") > 50 and t.count("}") > 50:
        return False, "looks_like_nested_json_dump"
    return True, "ok"

def _build_text_format_style_a(schema: Dict[str, Any], name: str) -> Dict[str, Any]:
    return {
        "format": {
            "type": "json_schema",
            "name": name,
            "strict": True,
            "schema": schema
        }
    }

def _build_text_format_style_b(schema: Dict[str, Any], name: str) -> Dict[str, Any]:
    return {
        "format": {
            "type": "json_schema",
            "json_schema": {
                "name": name,
                "strict": True,
                "schema": schema
            }
        }
    }

def _responses_create_openai_sdk(
    client: OpenAI,
    model: str,
    prompt: str,
    text_format: Dict[str, Any],
    tools: List[Dict[str, Any]],
    temperature: float,
    max_output_tokens: int,
    previous_response_id: Optional[str] = None
) -> Any:
    kwargs: Dict[str, Any] = {
        "model": model,
        "input": [
            {
                "role": "system",
                "content": [
                    {"type": "text", "text": "Te egy magyar nyelvű pretrain-dataset generátor vagy. A cél: maximális nyelvi minőség, minimális hallucináció. Csak JSON-t adj vissza."}
                ]
            },
            {
                "role": "user",
                "content": [{"type": "text", "text": prompt}]
            }
        ],
        "text": text_format,
        "tools": tools,
        "temperature": temperature,
        "max_output_tokens": max_output_tokens
    }
    if previous_response_id is not None:
        kwargs["previous_response_id"] = previous_response_id
    return client.responses.create(**kwargs)

def _responses_create_raw_http(
    api_key: str,
    base_url: str,
    payload: Dict[str, Any],
    timeout_s: float
) -> Dict[str, Any]:
    url = base_url.rstrip("/") + "/responses"
    data = _json_dumps(payload).encode("utf-8")
    req = urllib.request.Request(url, data=data, method="POST")
    req.add_header("Content-Type", "application/json")
    req.add_header("Authorization", f"Bearer {api_key}")
    with urllib.request.urlopen(req, timeout=timeout_s) as resp:
        b = resp.read()
    try:
        v = json.loads(b.decode("utf-8"))
        return v if isinstance(v, dict) else {"raw": b.decode("utf-8", errors="replace")}
    except Exception:
        return {"raw": b.decode("utf-8", errors="replace")}

def _attempt_generate_structured(
    client: OpenAI,
    model: str,
    prompt: str,
    schema: Dict[str, Any],
    tools: List[Dict[str, Any]],
    temperature: float,
    max_output_tokens: int,
    schema_name: str
) -> Tuple[Optional[Dict[str, Any]], List[str], Optional[str], Dict[str, Any], str]:
    last_err = ""
    for style in ("A", "B"):
        try:
            text_format = _build_text_format_style_a(schema, schema_name) if style == "A" else _build_text_format_style_b(schema, schema_name)
            resp = _responses_create_openai_sdk(
                client=client,
                model=model,
                prompt=prompt,
                text_format=text_format,
                tools=tools,
                temperature=temperature,
                max_output_tokens=max_output_tokens
            )
            text, citations, resp_id, raw = _extract_response_text_and_citations(resp)
            obj = _parse_json_lenient(text)
            if obj is not None:
                return obj, citations, resp_id, raw, f"responses_sdk_style_{style}"
            last_err = f"non_json_style_{style}"
        except Exception as e:
            last_err = f"{type(e).__name__}:{str(e)[:2000]}"
            continue
    return None, [], None, {}, last_err

def _attempt_repair_structured_stateful(
    client: OpenAI,
    model: str,
    schema: Dict[str, Any],
    tools: List[Dict[str, Any]],
    temperature: float,
    max_output_tokens: int,
    schema_name: str,
    previous_response_id: str,
    timeout_hint: float
) -> Tuple[Optional[Dict[str, Any]], List[str], Optional[str], Dict[str, Any], str]:
    repair_prompt = (
        "Az előző válaszod NEM felelt meg pontosan a JSON sémának.\n"
        "Feladat: az előző válaszod alapján adj vissza kizárólag egyetlen, érvényes, nyers JSON objektumot, ami pontosan megfelel a sémának.\n"
        "Ne adj semmilyen magyarázatot, csak a JSON-t.\n"
    )
    last_err = ""
    for style in ("A", "B"):
        try:
            text_format = _build_text_format_style_a(schema, schema_name) if style == "A" else _build_text_format_style_b(schema, schema_name)
            resp = _responses_create_openai_sdk(
                client=client,
                model=model,
                prompt=repair_prompt,
                text_format=text_format,
                tools=tools,
                temperature=temperature,
                max_output_tokens=max_output_tokens,
                previous_response_id=previous_response_id
            )
            text, citations, resp_id, raw = _extract_response_text_and_citations(resp)
            obj = _parse_json_lenient(text)
            if obj is not None:
                return obj, citations, resp_id, raw, f"repair_sdk_prev_style_{style}"
            last_err = f"repair_non_json_style_{style}"
        except Exception as e:
            last_err = f"{type(e).__name__}:{str(e)[:2000]}"
            continue
    return None, [], None, {}, last_err

def _attempt_repair_structured_raw_prevresponseid(
    api_key: str,
    base_url: str,
    model: str,
    schema: Dict[str, Any],
    schema_name: str,
    tools: List[Dict[str, Any]],
    temperature: float,
    max_output_tokens: int,
    previous_response_id: str,
    timeout_s: float
) -> Tuple[Optional[Dict[str, Any]], List[str], Optional[str], Dict[str, Any], str]:
    repair_prompt = (
        "Az előző válaszod NEM felelt meg pontosan a JSON sémának.\n"
        "Feladat: az előző válaszod alapján adj vissza kizárólag egyetlen, érvényes, nyers JSON objektumot, ami pontosan megfelel a sémának.\n"
        "Ne adj semmilyen magyarázatot, csak a JSON-t.\n"
    )
    text_format_a = _build_text_format_style_a(schema, schema_name)
    text_format_b = _build_text_format_style_b(schema, schema_name)
    last_err = ""
    for style, text_format in (("A", text_format_a), ("B", text_format_b)):
        payload = {
            "model": model,
            "previousresponseid": previous_response_id,
            "input": [
                {
                    "role": "system",
                    "content": [{"type": "text", "text": "Te egy magyar nyelvű pretrain-dataset generátor vagy. Csak JSON-t adj vissza."}]
                },
                {
                    "role": "user",
                    "content": [{"type": "text", "text": repair_prompt}]
                }
            ],
            "text": text_format,
            "tools": tools,
            "temperature": temperature,
            "max_output_tokens": max_output_tokens
        }
        try:
            raw = _responses_create_raw_http(api_key=api_key, base_url=base_url, payload=payload, timeout_s=timeout_s)
            text = ""
            citations: List[str] = []
            resp_id = raw.get("id") if isinstance(raw.get("id"), str) else None
            if isinstance(raw.get("citations"), list):
                for it in raw["citations"]:
                    if isinstance(it, str) and it.startswith("http"):
                        citations.append(it)
                    elif isinstance(it, dict):
                        u = it.get("url") or it.get("source") or it.get("link")
                        if isinstance(u, str) and u.startswith("http"):
                            citations.append(u)
            citations = list(dict.fromkeys(citations))
            if isinstance(raw.get("output_text"), str):
                text = raw["output_text"]
            elif isinstance(raw.get("output"), list):
                parts: List[str] = []
                for item in raw["output"]:
                    if isinstance(item, dict) and item.get("type") in ("output_text", "text") and isinstance(item.get("text"), str):
                        parts.append(item["text"])
                    if isinstance(item, dict) and item.get("type") == "message":
                        content = item.get("content")
                        if isinstance(content, list):
                            for c2 in content:
                                if isinstance(c2, dict) and c2.get("type") in ("output_text", "text") and isinstance(c2.get("text"), str):
                                    parts.append(c2["text"])
                if parts:
                    text = "".join(parts)
            obj = _parse_json_lenient(text)
            if obj is not None:
                return obj, citations, resp_id, raw, f"repair_raw_prevresponseid_style_{style}"
            last_err = f"repair_raw_non_json_style_{style}"
        except Exception as e:
            last_err = f"{type(e).__name__}:{str(e)[:2000]}"
            continue
    return None, [], None, {}, last_err

def _normalize_obj(
    obj: Dict[str, Any],
    citations: List[str],
    seed: int,
    task: Dict[str, str],
    min_chars: int
) -> Tuple[Optional[Dict[str, Any]], str]:
    if not isinstance(obj, dict):
        return None, "obj_not_dict"
    kind = obj.get("kind")
    domain = obj.get("domain")
    difficulty = obj.get("difficulty")
    content = obj.get("content")
    if kind != task["kind"]:
        return None, "kind_mismatch"
    if domain != task["domain"]:
        return None, "domain_mismatch"
    if difficulty != task["difficulty"]:
        return None, "difficulty_mismatch"
    ok, why = _quality_gate(content if isinstance(content, str) else "", min_chars)
    if not ok:
        return None, why
    sources: List[str] = []
    if isinstance(obj.get("sources"), list):
        for u in obj["sources"]:
            if isinstance(u, str) and u.startswith("http"):
                sources.append(u)
    for u in citations:
        if isinstance(u, str) and u.startswith("http"):
            sources.append(u)
    sources = list(dict.fromkeys(sources))
    content_str = content.strip()
    item_id = _mk_item_id(seed, kind, domain, content_str)
    is_factual = _needs_websearch(domain)
    halluc_risk = "low"
    notes = "Minimális hallucinációs kockázat: óvatos fogalmazás, ellenőrizhető állítások, és/vagy források használata."
    if is_factual and not sources:
        halluc_risk = "medium"
        notes = "Tényszerű domain forrás nélkül: a szöveg óvatos, általános, ellenőrizhetően megfogalmazott; konkrét, bizonytalan tények kerülve."
    out = {
        "id": item_id,
        "language": "hu",
        "kind": kind,
        "domain": domain,
        "difficulty": difficulty,
        "sources": sources,
        "content": content_str,
        "safety": {
            "pii": False,
            "copyright_safe": True,
            "hallucination_risk": halluc_risk,
            "notes": notes
        }
    }
    return out, "ok"

def _adaptive_max_tokens_on_error(err_text: str, current: int, floor: int) -> int:
    t = (err_text or "").lower()
    keys = ["max_output_tokens", "max tokens", "context", "context length", "too large", "exceeds", "limit"]
    if any(k in t for k in keys):
        nxt = max(floor, int(current * 0.6))
        if nxt == current:
            nxt = max(floor, current - 1024)
        return nxt
    return current

def main() -> None:
    api_key = _env_str("XAI_API_KEY", "XAIAPIKEY")
    if not api_key:
        raise ValueError("XAI_API_KEY vagy XAIAPIKEY nincs beállítva")

    base_url = _env_str("XAI_BASE_URL", default="") or ""
    model = _env_str("XAI_MODEL", default="grok-4-1-fast-reasoning") or "grok-4-1-fast-reasoning"

    out_dir = _env_str("OUT_DIR", default="datasets_hu_pretrain") or "datasets_hu_pretrain"
    prefix_ok = _env_str("FILE_PREFIX_OK", default="hu_pretrain_ok") or "hu_pretrain_ok"
    prefix_reject = _env_str("FILE_PREFIX_REJECT", default="hu_pretrain_reject") or "hu_pretrain_reject"
    bytes_per_file = _env_int("BYTES_PER_FILE", 1048576)

    seed_base = _env_int("SEED", int(time.time()))
    rng = random.Random(seed_base)

    temperature = _env_float("TEMPERATURE", 0.25)
    sleep_s = _env_float("SLEEP_SECONDS", 0.15)
    timeout_s = _env_float("HTTP_TIMEOUT_SECONDS", 3600.0)

    max_output_tokens = _env_int("MAX_OUTPUT_TOKENS", 131072)
    max_output_tokens = _clamp_int(max_output_tokens, 2048, 262144)

    min_chars = _env_int("MIN_CONTENT_CHARS", 1200)
    min_chars = _clamp_int(min_chars, 800, 20000)

    schema = _build_json_schema()
    schema_name = _env_str("SCHEMA_NAME", default="hu_pretrain_item") or "hu_pretrain_item"
    catalog = _task_catalog()

    _mkdirp(out_dir)
    writer_ok = _RotatingJsonlWriter(out_dir=out_dir, prefix=prefix_ok, bytes_per_file=bytes_per_file)
    writer_reject = _RotatingJsonlWriter(out_dir=out_dir, prefix=prefix_reject, bytes_per_file=bytes_per_file)

    client = OpenAI(api_key=api_key, base_url=base_url, timeout=timeout_s)

    produced_ok = 0
    produced_reject = 0
    consecutive_failures = 0
    backoff = 1.0

    print(f"START {_utc_iso()} base_url={base_url} model={model} out_dir={out_dir} bytes_per_file={bytes_per_file} max_output_tokens={max_output_tokens} min_chars={min_chars}", flush=True)

    while True:
        seed = rng.randrange(0, 2_000_000_000)
        task = catalog[rng.randrange(0, len(catalog))]
        prompt = _prompt_for_task(task, seed)
        use_websearch = _needs_websearch(task["domain"])
        tools: List[Dict[str, Any]] = [{"type": "websearch"}] if use_websearch else []

        print(f"REQ {_utc_iso()} ok={produced_ok} reject={produced_reject} kind={task['kind']} domain={task['domain']} diff={task['difficulty']} websearch={str(use_websearch).lower()} mot={max_output_tokens}", flush=True)

        gen_mode = ""
        raw_resp_id: Optional[str] = None
        raw_dump: Dict[str, Any] = {}
        citations: List[str] = []
        obj_candidate: Optional[Dict[str, Any]] = None
        err_text = ""

        try:
            obj_candidate, citations, raw_resp_id, raw_dump, gen_mode = _attempt_generate_structured(
                client=client,
                model=model,
                prompt=prompt,
                schema=schema,
                tools=tools,
                temperature=temperature,
                max_output_tokens=max_output_tokens,
                schema_name=schema_name
            )

            if obj_candidate is None:
                err_text = f"initial_failed:{gen_mode}"
                if raw_resp_id:
                    repair_obj, repair_cit, repair_id, repair_dump, repair_mode = _attempt_repair_structured_stateful(
                        client=client,
                        model=model,
                        schema=schema,
                        tools=tools,
                        temperature=max(0.0, min(temperature, 0.2)),
                        max_output_tokens=max_output_tokens,
                        schema_name=schema_name,
                        previous_response_id=raw_resp_id,
                        timeout_hint=timeout_s
                    )
                    if repair_obj is not None:
                        obj_candidate = repair_obj
                        citations = list(dict.fromkeys(citations + repair_cit))
                        raw_resp_id = repair_id or raw_resp_id
                        raw_dump = repair_dump or raw_dump
                        gen_mode = repair_mode
                if obj_candidate is None and raw_resp_id:
                    repair_obj2, repair_cit2, repair_id2, repair_dump2, repair_mode2 = _attempt_repair_structured_raw_prevresponseid(
                        api_key=api_key,
                        base_url=base_url,
                        model=model,
                        schema=schema,
                        schema_name=schema_name,
                        tools=tools,
                        temperature=max(0.0, min(temperature, 0.2)),
                        max_output_tokens=max_output_tokens,
                        previous_response_id=raw_resp_id,
                        timeout_s=timeout_s
                    )
                    if repair_obj2 is not None:
                        obj_candidate = repair_obj2
                        citations = list(dict.fromkeys(citations + repair_cit2))
                        raw_resp_id = repair_id2 or raw_resp_id
                        raw_dump = repair_dump2 or raw_dump
                        gen_mode = repair_mode2

            if obj_candidate is None:
                reject = {
                    "ts": _utc_iso(),
                    "reason": "no_valid_json_after_attempts",
                    "mode": gen_mode,
                    "seed": seed,
                    "task": task,
                    "model": model,
                    "max_output_tokens": max_output_tokens,
                    "prompt_sha256": _sha256_hex(prompt),
                    "response_id": raw_resp_id,
                    "citations": citations,
                    "raw": raw_dump
                }
                path, idx, b = writer_reject.write(reject)
                produced_reject += 1
                consecutive_failures += 1
                backoff = min(60.0, backoff * 1.4) if consecutive_failures >= 2 else 1.0
                print(f"REJECT {_utc_iso()} file={os.path.basename(path)} idx={idx} bytes={b} failures={consecutive_failures} backoff={backoff:.2f}s reason=no_valid_json mode={gen_mode}", flush=True)
                if sleep_s > 0:
                    time.sleep(sleep_s)
                continue

            normalized, why = _normalize_obj(obj_candidate, citations, seed, task, min_chars)
            if normalized is None:
                reject = {
                    "ts": _utc_iso(),
                    "reason": f"quality_or_schema_gate:{why}",
                    "mode": gen_mode,
                    "seed": seed,
                    "task": task,
                    "model": model,
                    "max_output_tokens": max_output_tokens,
                    "prompt_sha256": _sha256_hex(prompt),
                    "response_id": raw_resp_id,
                    "citations": citations,
                    "obj": obj_candidate,
                    "raw": raw_dump
                }
                path, idx, b = writer_reject.write(reject)
                produced_reject += 1
                consecutive_failures += 1
                backoff = min(60.0, backoff * 1.4) if consecutive_failures >= 2 else 1.0
                print(f"REJECT {_utc_iso()} file={os.path.basename(path)} idx={idx} bytes={b} failures={consecutive_failures} backoff={backoff:.2f}s reason={why} mode={gen_mode}", flush=True)
                if sleep_s > 0:
                    time.sleep(sleep_s)
                continue

            meta = {
                "generated_at": _utc_iso(),
                "model": model,
                "seed": seed,
                "mode": gen_mode,
                "response_id": raw_resp_id,
                "content_sha256": _sha256_hex(normalized["content"])
            }
            out = dict(normalized)
            out["meta"] = meta

            path, idx, b = writer_ok.write(out)
            produced_ok += 1
            consecutive_failures = 0
            backoff = 1.0

            print(f"OK {_utc_iso()} n={produced_ok} file={os.path.basename(path)} idx={idx} bytes={b} id={out['id']} kind={out['kind']} domain={out['domain']} diff={out['difficulty']} mode={gen_mode}", flush=True)

            if sleep_s > 0:
                time.sleep(sleep_s)

        except KeyboardInterrupt:
            print(f"STOP {_utc_iso()} ok={produced_ok} reject={produced_reject}", flush=True)
            break
        except Exception as e:
            tb = traceback.format_exc()
            err_text = f"{type(e).__name__}:{str(e)}"
            max_output_tokens = _adaptive_max_tokens_on_error(err_text + " " + tb, max_output_tokens, 4096)
            reject = {
                "ts": _utc_iso(),
                "reason": "exception",
                "error": err_text,
                "traceback": tb,
                "seed": seed,
                "task": task,
                "model": model,
                "max_output_tokens": max_output_tokens,
                "prompt_sha256": _sha256_hex(prompt),
                "response_id": raw_resp_id,
                "citations": citations,
                "raw": raw_dump
            }
            try:
                path, idx, b = writer_reject.write(reject)
                produced_reject += 1
            except Exception:
                pass
            consecutive_failures += 1
            backoff = min(60.0, backoff * 1.7) if consecutive_failures >= 2 else 1.0
            print(f"ERR {_utc_iso()} failures={consecutive_failures} backoff={backoff:.2f}s max_output_tokens={max_output_tokens} error={err_text}", file=sys.stderr, flush=True)
            time.sleep(backoff)

if __name__ == "__main__":
    main()
